WITH h AS (
  SELECT SUM(paid_hours) AS paid_hours FROM shifts
  WHERE program='vr' AND shift_date BETWEEN '2026-10-05' AND '2026-10-11'
), c AS (
  SELECT COUNT(*) FILTER (WHERE NOT is_duplicate) AS valid_cards FROM vr_cards
  WHERE collected_at >= '2026-10-05' AND collected_at < '2026-10-12'
)
SELECT c.valid_cards, ROUND(h.paid_hours,2) AS paid_hours, ROUND(c.valid_cards/h.paid_hours,2) AS cards_per_hour FROM h, c;
